steps.code:
# Let's re-parse the file content properly, removing the "- " prefix and skipping the header
file_content = _mem['s10']['content']
lines = file_content.strip().split('\n')
songs_to_archive = []
for line in lines:
    line = line.strip()
    if not line or line.startswith('#'):
        continue
    # Remove leading "- " if present
    if line.startswith('- '):
        line = line[2:]
    if ' by ' in line:
        title, artist = line.rsplit(' by ', 1)
        songs_to_archive.append((title.strip(), artist.strip()))
    else:
        print("Unparsed line:", line)
print("Parsed songs:", len(songs_to_archive))
for t, a in songs_to_archive:
    print(f"  {t} by {a}")

