steps.code:
# Parse the file content to get list of (title, artist) pairs
content = _mem['s10']['content']
archive_songs = []
for line in content.splitlines():
    line = line.strip()
    if not line or line.startswith('#'):
        continue
    if line.startswith('- '):
        line = line[2:]
    if ' by ' in line:
        title, artist = line.rsplit(' by ', 1)
        archive_songs.append((title.strip(), artist.strip()))
print(f"Parsed {len(archive_songs)} songs from file")
for t, a in archive_songs:
    print(f"  {t} by {a}")

