# Parse the archived songs from the file content
file_content = _mem['s10']['content']
archived_songs = []
for line in file_content.splitlines():
    line = line.strip()
    if not line or line.startswith('#'):
        continue
    if line.startswith('- '):
        line = line[2:]
    if ' by ' in line:
        title, artist = line.rsplit(' by ', 1)
        archived_songs.append((title.strip(), artist.strip()))
print("Archived songs parsed:", len(archived_songs))
for t, a in archived_songs:
    print(f"  {t} by {a}")

